/**
 * 20 reference charts with expected positions from independent sources.
 *
 * Nothing here is produced by this app. The values were frozen from:
 *   - UTC instant: IANA tzdata (zoneinfo), so timezone and DST handling is testable
 *   - Sun through Pluto and Chiron: JPL Horizons apparent geocentric RA/Dec,
 *     converted to ecliptic longitude of date
 *   - Ascendant and Midheaven: Meeus sidereal-time formulae at the city coordinates
 *   - North Node: Meeus mean lunar node (the app uses the true node, so this body
 *     carries a wide tolerance and is reported as a sanity check)
 *
 * Expected values are absolute ecliptic longitude in degrees (0 = 0 Aries).
 */

export interface ReferencePerson {
  id: string;
  name: string;
  birthDate: string;
  birthTime: string;
  birthLocation: string;
  /** IANA zone used to derive the authoritative UTC instant. */
  timezone: string;
  /** Authoritative UTC instant for the birth moment. */
  utc: string;
  /** Correct local offset in hours at that moment. */
  utcOffsetHours: number;
  lat: number;
  lon: number;
  /** Birth time is a noon assumption, so angles are informational only. */
  approximateTime: boolean;
  /** Why this chart is in the set. */
  why: string;
  /** Absolute ecliptic longitude in degrees. */
  expected: Record<string, number>;
}

